  function openToolLibrary(){libraryOpener=document.activeElement;if(!ui.library)return;ui.library.hidden=false;document.body.style.overflow='hidden';if(ui.toolSearch){ui.toolSearch.value='';filterToolLibrary('');setTimeout(()=>ui.toolSearch.focus(),30)}renderFavoriteUi()}
