  function filterToolLibrary(q=''){const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();q=normalize(q).trim();let shown=0;$$('[data-library-tool]',ui.libraryGroups).forEach(b=>{const text=normalize(`${b.dataset.search||''} ${b.textContent}`),ok=!q||text.includes(q);b.hidden=!ok;if(ok)shown++});$$('[data-tool-category]',ui.libraryGroups).forEach(sec=>{sec.hidden=!$$('[data-library-tool]',sec).some(b=>!b.hidden)});if(ui.libraryEmpty)ui.libraryEmpty.hidden=shown>0}
  function formatBytes(bytes){const u=['o','Ko','Mo','Go'];let n=Number(bytes)||0,i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return`${n>=10||i===0?n.toFixed(0):n.toFixed(1)} ${u[i]}`}
  function setBusy(v){state.busy=!!v;ui.reset.disabled=!!v;ui.toolButtons.forEach(b=>b.disabled=!!v)}
  function progress(label,value=0){ui.progress.hidden=false;ui.progressLabel.textContent=label;ui.progressBar.value=clamp(value,0,100);ui.progressPercent.textContent=`${Math.round(value)} %`}
