  function fileChip(file,extra=''){const d=document.createElement('div');d.className='pdf-file-chip';d.innerHTML='<span>PDF</span><div><strong></strong><small></small></div>';$('strong',d).textContent=file.name;$('small',d).textContent=`${formatBytes(file.size)}${extra?` · ${extra}`:''}`;return d}
