  function clearWorkbench(){state.files=[];state.pdfjsDoc=null;state.pdfPageCount=0;state.organizePages=[];state.organizeSources=new Map();state.organizeImages=new Map();state.organizeSelected=new Set();state.organizeLastSelected=null;state.organizeHistory=[];state.organizeRedo=[];state.mergeDocs=[];state.mergeExpert=false;state.mergePageOrder=[];state.splitSelected=new Set();state.composeSelected=[];state.composeCrop={};state.interleaveDocs=[];state.scanAngles={};state.scanPreviewCanvas=null;state.editorPage=0;state.editorAnnotations=[];state.editorSelected=null;state.outlineEntries=[];state.dragIndex=null;ui.fileInput.value='';ui.summary.innerHTML='';ui.controls.innerHTML='';ui.content.innerHTML='';ui.actionRow.innerHTML='';ui.panel.hidden=true;ui.dropzone.hidden=false;hideMessage();hideProgress()}
  function selectTool(tool,{remember=true,scroll=true}={}){if(state.busy||!tools[tool])return;state.tool=tool;ui.toolButtons.forEach(b=>{const a=b.dataset.tool===tool;b.classList.toggle('is-active',a);b.setAttribute('aria-pressed',String(a))});const m=tools[tool];ui.kicker.textContent=m.kicker;ui.title.textContent=m.title;ui.description.textContent=m.description;ui.dropTitle.textContent=m.drop;ui.dropNote.textContent=m.note;ui.fileInput.accept=m.accept;ui.fileInput.multiple=m.multiple;clearWorkbench();if(tool==='presets')setupPresetsHome();if(remember)rememberTool(tool);renderFavoriteUi();closeToolLibrary();if(scroll)document.querySelector('[data-workbench]')?.scrollIntoView({behavior:'smooth',block:'start'})}
  function validateFiles(files){const meta=tools[state.tool];let list=[...files];if(!meta.multiple)list=list.slice(0,1);if(state.tool==='images-to-pdf')return list.filter(f=>/image\/(jpeg|png)/i.test(f.type)||/\.(jpe?g|png)$/i.test(f.name));return list.filter(f=>/application\/pdf/i.test(f.type)||/\.pdf$/i.test(f.name))}
