  async function renderThumb(doc,pageNumber,canvas,{rotation=0,maxW=210,maxH=260}={}){try{const page=await doc.getPage(pageNumber),v0=page.getViewport({scale:1,rotation:(page.rotate+rotation)%360}),scale=Math.min(maxW/v0.width,maxH/v0.height,1),v=page.getViewport({scale,rotation:(page.rotate+rotation)%360}),ctx=canvas.getContext('2d',{alpha:false});canvas.width=Math.max(1,Math.ceil(v.width));canvas.height=Math.max(1,Math.ceil(v.height));ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);await page.render({canvasContext:ctx,viewport:v}).promise}catch(e){console.warn(e)}}
  function cropStyle(c){const top=clamp(c?.top,0,45),right=clamp(c?.right,0,45),bottom=clamp(c?.bottom,0,45),left=clamp(c?.left,0,45);return`inset(${top}% ${right}% ${bottom}% ${left}%)`}
