  async function exportOrganized(){if(!state.organizePages.length){showMessage('Il faut conserver au moins une page.','error');return}setBusy(true);progress('Création du PDF…',5);hideMessage();try{const out=await PDFDocument.create(),physical=$('[data-crop-mode]',ui.controls)?.value==='physical',loaded=new Map(),images=new Map();for(const[id,src]of state.organizeSources.entries())loaded.set(id,await PDFDocument.load(await src.file.arrayBuffer()));for(let i=0;i<state.organizePages.length;i++){const item=state.organizePages[i];if(item.kind==='pdf'){const src=loaded.get(item.docId||'main'),[copy]=await out.copyPages(src,[item.source]);copy.setRotation(degrees((copy.getRotation().angle+item.rotation)%360));applyCropToPage(copy,item.crop,physical);out.addPage(copy)}else if(item.kind==='blank'){const page=out.addPage([item.width,item.height]);if(item.rotation)page.setRotation(degrees(item.rotation))}else if(item.kind==='image'){const file=state.organizeImages.get(item.imageId);if(file){let img=images.get(item.imageId);if(!img){const data=await file.arrayBuffer();img=/png/i.test(file.type)||/\.png$/i.test(file.name)?await out.embedPng(data):await out.embedJpg(data);images.set(item.imageId,img)}const[pw,ph]=A4P,page=out.addPage([pw,ph]),margin=24,scale=Math.min((pw-margin*2)/img.width,(ph-margin*2)/img.height),w=img.width*scale,h=img.height*scale;page.drawImage(img,{x:(pw-w)/2,y:(ph-h)/2,width:w,height:h});if(item.rotation)page.setRotation(degrees(item.rotation))}}progress('Création du PDF…',10+((i+1)/state.organizePages.length)*80);if(i%5===4)await tick()}await downloadBytes(await out.save({useObjectStreams:true}),`${baseName(state.files[0].name)}-modifie.pdf`);showMessage('PDF prêt pour la vérification finale.')}catch(e){console.error(e);showMessage('Impossible de générer le PDF modifié.','error')}finally{hideProgress();setBusy(false)}}

