  async function setupMerge(){setBusy(true);progress('Création des aperçus…',5);try{state.mergeDocs=[];state.mergeExpert=false;state.mergePageOrder=[];for(let i=0;i<state.files.length;i++){const file=state.files[i],pdfjs=await getPdfJs(file);state.mergeDocs.push({file,pdfjs,pages:pdfjs.numPages,expanded:false});progress(`PDF ${i+1}/${state.files.length}`,10+70*(i+1)/state.files.length);await tick()}state.mergeDocs.forEach((d,docIndex)=>{for(let p=0;p<d.pages;p++)state.mergePageOrder.push({docIndex,pageIndex:p})});refreshMergeSummary();ui.controls.innerHTML='<div class="pdf-field grow"><span>Affichage</span><div class="pdf-inline-note" data-merge-mode-note>Mode documents : déplace les PDF entiers. Passe en mode expert pour déplacer ou supprimer des pages individuelles entre plusieurs documents.</div></div>';await renderMergeDocs();addPrimary('Fusionner et télécharger',mergePdfs);addSecondary('＋ Ajouter des PDF',addMergeFiles);addSecondary('Mode expert · pages',()=>{const goingExpert=!state.mergeExpert;if(goingExpert){state.mergePageOrder=[];state.mergeDocs.forEach((d,docIndex)=>{for(let p=0;p<d.pages;p++)state.mergePageOrder.push({docIndex,pageIndex:p})})}state.mergeExpert=goingExpert;const n=$('[data-merge-mode-note]',ui.controls);if(n)n.textContent=state.mergeExpert?'Mode expert : toutes les pages sont maintenant dans un seul ordre visuel. Glisse, déplace ou supprime une page avant la fusion.':'Mode documents : déplace les PDF entiers. Passe en mode expert pour déplacer ou supprimer des pages individuelles entre plusieurs documents.';renderMergeDocs()})}finally{hideProgress();setBusy(false)}}
  function refreshMergeSummary(){ui.summary.innerHTML='';state.mergeDocs.forEach(d=>ui.summary.appendChild(fileChip(d.file,`${d.pages} page${d.pages>1?'s':''}`)))}
  async function renderMergeExpert(){ui.content.innerHTML='<div class="pdf-pages pdf-pages-large" data-merge-page-grid></div>';const grid=$('[data-merge-page-grid]',ui.content);for(let i=0;i<state.mergePageOrder.length;i++){const item=state.mergePageOrder[i],doc=state.mergeDocs[item.docIndex],card=document.createElement('article');card.className='pdf-page-card pdf-page-editor';card.draggable=true;card.dataset.index=i;card.innerHTML=`<div class="pdf-page-preview"><canvas></canvas><span class="pdf-drag-handle">⋮⋮</span></div><div class="pdf-page-title"><span>Position ${i+1}</span><small>${String.fromCharCode(65+item.docIndex)} · p. ${item.pageIndex+1}</small></div><div class="pdf-page-actions"><button data-act="left">←</button><button data-act="right">→</button><button data-act="duplicate">⧉</button><button data-act="delete" class="is-danger">×</button></div>`;grid.appendChild(card);await renderThumb(doc.pdfjs,item.pageIndex+1,$('canvas',card),{maxW:220,maxH:285});$('.pdf-page-actions',card).addEventListener('click',e=>{const act=e.target.closest('button')?.dataset.act,idx=Number(card.dataset.index);if(act==='left'&&idx>0)[state.mergePageOrder[idx-1],state.mergePageOrder[idx]]=[state.mergePageOrder[idx],state.mergePageOrder[idx-1]];else if(act==='right'&&idx<state.mergePageOrder.length-1)[state.mergePageOrder[idx+1],state.mergePageOrder[idx]]=[state.mergePageOrder[idx],state.mergePageOrder[idx+1]];else if(act==='duplicate')state.mergePageOrder.splice(idx+1,0,{...state.mergePageOrder[idx]});else if(act==='delete')state.mergePageOrder.splice(idx,1);else return;renderMergeExpert()});card.addEventListener('dragstart',()=>{state.dragIndex=Number(card.dataset.index);card.classList.add('is-dragging')});card.addEventListener('dragend',()=>{state.dragIndex=null;card.classList.remove('is-dragging')});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();const from=state.dragIndex,to=Number(card.dataset.index);if(from==null||from===to)return;const[m]=state.mergePageOrder.splice(from,1);state.mergePageOrder.splice(to,0,m);renderMergeExpert()});if(i%5===4)await tick()}}
function addMergeFiles(){const input=document.createElement('input');input.type='file';input.accept='application/pdf,.pdf';input.multiple=true;input.addEventListener('change',async()=>{const extra=validateFiles(input.files);if(!extra.length)return;setBusy(true);progress('Ajout des PDF…',5);try{for(let i=0;i<extra.length;i++){const file=extra[i],pdfjs=await getPdfJs(file);state.mergeDocs.push({file,pdfjs,pages:pdfjs.numPages,expanded:false});const docIndex=state.mergeDocs.length-1;for(let p=0;p<pdfjs.numPages;p++)state.mergePageOrder.push({docIndex,pageIndex:p});state.files.push(file)}refreshMergeSummary();await renderMergeDocs()}finally{hideProgress();setBusy(false)}});input.click()}
  async function renderMergeDocs(){if(state.mergeExpert)return renderMergeExpert();ui.content.innerHTML='<div class="pdf-merge-list" data-merge-list></div>';const list=$('[data-merge-list]',ui.content);for(let i=0;i<state.mergeDocs.length;i++){const d=state.mergeDocs[i],card=document.createElement('article');card.className='pdf-merge-card';card.draggable=true;card.dataset.index=i;card.innerHTML=`<header><span class="pdf-file-index">${i+1}</span><div><strong>${escapeHtml(d.file.name)}</strong><small>${d.pages} page${d.pages>1?'s':''} · ${formatBytes(d.file.size)}</small></div><div class="pdf-row-actions"><button class="pdf-mini-btn" data-act="up">↑</button><button class="pdf-mini-btn" data-act="down">↓</button><button class="pdf-mini-btn" data-act="expand">${d.expanded?'−':'▦'}</button><button class="pdf-mini-btn is-danger" data-act="remove">×</button></div></header><div class="pdf-merge-previews"></div>`;list.appendChild(card);const preview=$('.pdf-merge-previews',card),indices=d.expanded?Array.from({length:d.pages},(_,n)=>n+1):[1,Math.max(1,Math.ceil(d.pages/2)),d.pages].filter((v,n,a)=>a.indexOf(v)===n);for(const n of indices){const f=document.createElement('figure');f.innerHTML='<div><canvas></canvas></div><figcaption></figcaption>';$('figcaption',f).textContent=`p. ${n}`;preview.appendChild(f);await renderThumb(d.pdfjs,n,$('canvas',f),{maxW:150,maxH:190})}$('.pdf-row-actions',card).addEventListener('click',e=>{const act=e.target.closest('button')?.dataset.act;if(!act)return;const idx=Number(card.dataset.index);if(act==='up'&&idx>0)[state.mergeDocs[idx-1],state.mergeDocs[idx]]=[state.mergeDocs[idx],state.mergeDocs[idx-1]];else if(act==='down'&&idx<state.mergeDocs.length-1)[state.mergeDocs[idx+1],state.mergeDocs[idx]]=[state.mergeDocs[idx],state.mergeDocs[idx+1]];else if(act==='expand'){state.mergeDocs[idx].expanded=!state.mergeDocs[idx].expanded}else if(act==='remove')state.mergeDocs.splice(idx,1);else return;state.files=state.mergeDocs.map(x=>x.file);refreshMergeSummary();renderMergeDocs()});card.addEventListener('dragstart',()=>state.dragIndex=Number(card.dataset.index));card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();const from=state.dragIndex,to=Number(card.dataset.index);if(from==null||from===to)return;const [m]=state.mergeDocs.splice(from,1);state.mergeDocs.splice(to,0,m);state.files=state.mergeDocs.map(x=>x.file);refreshMergeSummary();renderMergeDocs()})}}
  function escapeHtml(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  async function mergePdfs(){if(!state.mergeDocs.length){showMessage('Ajoute au moins un PDF.','error');return}setBusy(true);progress('Fusion…',4);try{const out=await PDFDocument.create();if(state.mergeExpert){if(!state.mergePageOrder.length){showMessage('Il ne reste aucune page à fusionner.','error');return}const loaded=[];for(let i=0;i<state.mergeDocs.length;i++)loaded.push(await PDFDocument.load(await state.mergeDocs[i].file.arrayBuffer()));for(let i=0;i<state.mergePageOrder.length;i++){const item=state.mergePageOrder[i],[copy]=await out.copyPages(loaded[item.docIndex],[item.pageIndex]);out.addPage(copy);progress(`Page ${i+1}/${state.mergePageOrder.length}`,8+84*(i+1)/state.mergePageOrder.length);if(i%6===5)await tick()}downloadBytes(await out.save({useObjectStreams:true}),'pdf-fusionnes-pages.pdf');showMessage(`${state.mergePageOrder.length} pages fusionnées dans l’ordre affiché.`)}else{for(let i=0;i<state.mergeDocs.length;i++){const src=await PDFDocument.load(await state.mergeDocs[i].file.arrayBuffer()),pages=await out.copyPages(src,src.getPageIndices());pages.forEach(p=>out.addPage(p));progress(`Document ${i+1}/${state.mergeDocs.length}`,8+84*(i+1)/state.mergeDocs.length);await tick()}downloadBytes(await out.save({useObjectStreams:true}),'pdf-fusionnes.pdf');showMessage(`${state.mergeDocs.length} PDF fusionnés dans l’ordre affiché.`)}}catch(e){console.error(e);showMessage('Fusion impossible.','error')}finally{hideProgress();setBusy(false)}}

  /* COMPOSER 2 -> 1 */
  async function setupCompose(){const file=state.files[0];setBusy(true);progress('Miniatures…',5);try{state.pdfjsDoc=await getPdfJs(file);state.pdfPageCount=state.pdfjsDoc.numPages;state.composeSelected=[];state.composeCrop={};ui.summary.appendChild(fileChip(file,`${state.pdfPageCount} page${state.pdfPageCount>1?'s':''}`));ui.controls.innerHTML=`<div class="pdf-field"><span>Disposition</span><select data-compose-layout><option value="vertical">L’une sous l’autre</option><option value="horizontal">Côte à côte</option></select></div><div class="pdf-field"><span>Feuille finale</span><select data-compose-size><option value="a4p">A4 portrait</option><option value="a4l">A4 paysage</option><option value="auto">Format ajusté</option></select></div><div class="pdf-field"><span>Marge</span><input data-compose-margin type="number" min="0" max="100" value="24"></div><div class="pdf-field"><span>Espace entre pages</span><input data-compose-gap type="number" min="0" max="100" value="16"></div>`;await renderComposePages();addPrimary('Créer la page assemblée',composeTwoPages)}finally{hideProgress();setBusy(false)}}
  async function renderComposePages(){ui.content.innerHTML='<div class="pdf-compose-selected" data-compose-selected></div><div class="pdf-pages pdf-select-pages" data-compose-pages></div>';const grid=$('[data-compose-pages]',ui.content);for(let i=0;i<state.pdfPageCount;i++){const card=document.createElement('button');card.type='button';card.className=`pdf-select-card${state.composeSelected.includes(i)?' is-selected':''}`;card.innerHTML=`<div class="pdf-page-preview"><canvas></canvas><span class="pdf-select-number">${i+1}</span></div><strong>Page ${i+1}</strong>`;card.addEventListener('click',()=>{const pos=state.composeSelected.indexOf(i);if(pos>=0)state.composeSelected.splice(pos,1);else if(state.composeSelected.length<2)state.composeSelected.push(i);else state.composeSelected[1]=i;if(!state.composeCrop[i])state.composeCrop[i]=defaultCrop();renderComposePages()});grid.appendChild(card);await renderThumb(state.pdfjsDoc,i+1,$('canvas',card),{maxW:190,maxH:235});if(i%5===4)await tick()}renderComposeSelected()}
  function renderComposeSelected(){const z=$('[data-compose-selected]',ui.content);if(!z)return;if(state.composeSelected.length!==2){z.innerHTML='<div class="pdf-empty-inline">Sélectionne exactement <strong>2 pages</strong>. Elles apparaîtront ici avec leur propre recadrage.</div>';return}z.innerHTML=`<div class="pdf-compose-picks">${state.composeSelected.map((pageIdx,slot)=>{const c=state.composeCrop[pageIdx]||defaultCrop();return`<article><span class="meta">Page ${pageIdx+1} · ${slot===0?'A':'B'}</span><div class="pdf-compose-crop-preview"><div style="clip-path:${cropStyle(c)}"></div><canvas data-compose-thumb="${pageIdx}"></canvas></div>${['top','right','bottom','left'].map(k=>`<label><span>${{top:'Haut',right:'Droite',bottom:'Bas',left:'Gauche'}[k]}</span><input type="range" min="0" max="45" value="${c[k]}" data-compose-crop="${pageIdx}:${k}"><output>${c[k]} %</output></label>`).join('')}</article>`}).join('')}</div>`;state.composeSelected.forEach(async pageIdx=>{await renderThumb(state.pdfjsDoc,pageIdx+1,$(`[data-compose-thumb="${pageIdx}"]`,z),{maxW:260,maxH:290})});z.querySelectorAll('[data-compose-crop]').forEach(i=>i.addEventListener('input',()=>{const[page,k]=i.dataset.composeCrop.split(':');state.composeCrop[page][k]=Number(i.value);i.nextElementSibling.textContent=`${i.value} %`;renderComposeSelected()}))}
  function cropBoxFromPage(page,crop){const c=normalizedCrop(crop),box=page.getCropBox?.()||page.getMediaBox?.()||{x:0,y:0,width:page.getWidth(),height:page.getHeight()};return{left:box.x+box.width*c.left/100,bottom:box.y+box.height*c.bottom/100,right:box.x+box.width*(1-c.right/100),top:box.y+box.height*(1-c.top/100)}}
  async function composeTwoPages(){if(state.composeSelected.length!==2){showMessage('Sélectionne deux pages.','error');return}setBusy(true);progress('Assemblage…',10);try{const src=await PDFDocument.load(await state.files[0].arrayBuffer()),out=await PDFDocument.create(),layout=$('[data-compose-layout]',ui.controls).value,size=$('[data-compose-size]',ui.controls).value,margin=clamp($('[data-compose-margin]',ui.controls).value,0,100),gap=clamp($('[data-compose-gap]',ui.controls).value,0,100),embeds=[];for(const idx of state.composeSelected){const page=src.getPage(idx),bb=cropBoxFromPage(page,state.composeCrop[idx]);embeds.push(await out.embedPage(page,bb))}let pw,ph;if(size==='a4p')[pw,ph]=A4P;else if(size==='a4l')[pw,ph]=A4L;else{if(layout==='vertical'){pw=Math.max(...embeds.map(e=>e.width))+margin*2;ph=embeds.reduce((a,e)=>a+e.height,0)+gap+margin*2}else{pw=embeds.reduce((a,e)=>a+e.width,0)+gap+margin*2;ph=Math.max(...embeds.map(e=>e.height))+margin*2}}const page=out.addPage([pw,ph]);if(layout==='vertical'){const slotH=(ph-margin*2-gap)/2;embeds.forEach((e,i)=>{const scale=Math.min((pw-margin*2)/e.width,slotH/e.height),w=e.width*scale,h=e.height*scale,x=(pw-w)/2,y=ph-margin-(i+1)*slotH-i*gap+(slotH-h)/2;page.drawPage(e,{x,y,width:w,height:h})})}else{const slotW=(pw-margin*2-gap)/2;embeds.forEach((e,i)=>{const scale=Math.min(slotW/e.width,(ph-margin*2)/e.height),w=e.width*scale,h=e.height*scale,x=margin+i*(slotW+gap)+(slotW-w)/2,y=(ph-h)/2;page.drawPage(e,{x,y,width:w,height:h})})}downloadBytes(await out.save({useObjectStreams:true}),`${baseName(state.files[0].name)}-2-pages-en-1.pdf`);showMessage('Les deux pages ont été assemblées sur une seule feuille.')}catch(e){console.error(e);showMessage('Assemblage impossible sur ce PDF.','error')}finally{hideProgress();setBusy(false)}}

  /* EXTRAIRE / DIVISER */
  async function setupSplit(){const file=state.files[0];setBusy(true);progress('Miniatures…',5);try{state.pdfjsDoc=await getPdfJs(file);state.pdfPageCount=state.pdfjsDoc.numPages;state.splitSelected=new Set(Array.from({length:state.pdfPageCount},(_,i)=>i));ui.summary.appendChild(fileChip(file,`${state.pdfPageCount} page${state.pdfPageCount>1?'s':''}`));ui.controls.innerHTML=`<div class="pdf-field grow"><span>Sélection rapide</span><input type="text" data-ranges placeholder="Ex. 1-3, 6, 9-12"></div><div class="button-row"><button class="pdf-secondary" data-select-all>Tout</button><button class="pdf-secondary" data-select-none>Aucun</button><button class="pdf-secondary" data-select-invert>Inverser</button><button class="pdf-secondary" data-select-odd>Impaires</button><button class="pdf-secondary" data-select-even>Paires</button></div><div class="pdf-field"><span>Lots de</span><input data-chunk-size type="number" min="1" value="5"></div>`;await renderSplitPages();$('[data-ranges]',ui.controls).addEventListener('change',()=>{const arr=parseRanges($('[data-ranges]',ui.controls).value,state.pdfPageCount);state.splitSelected=new Set(arr.map(n=>n-1));renderSplitPages()});$('[data-select-all]',ui.controls).addEventListener('click',()=>{state.splitSelected=new Set(Array.from({length:state.pdfPageCount},(_,i)=>i));renderSplitPages()});$('[data-select-none]',ui.controls).addEventListener('click',()=>{state.splitSelected.clear();renderSplitPages()});$('[data-select-invert]',ui.controls).addEventListener('click',()=>{const n=new Set();for(let i=0;i<state.pdfPageCount;i++)if(!state.splitSelected.has(i))n.add(i);state.splitSelected=n;renderSplitPages()});$('[data-select-odd]',ui.controls).addEventListener('click',()=>{state.splitSelected=new Set(Array.from({length:state.pdfPageCount},(_,i)=>i).filter(i=>i%2===0));renderSplitPages()});$('[data-select-even]',ui.controls).addEventListener('click',()=>{state.splitSelected=new Set(Array.from({length:state.pdfPageCount},(_,i)=>i).filter(i=>i%2===1));renderSplitPages()});addPrimary('Exporter la sélection',extractPages);addSecondary('1 fichier par page',exportEachSelectedPage);addSecondary('Découper en lots',splitIntoChunks)}finally{hideProgress();setBusy(false)}}
  function parseRanges(text,max){const set=new Set();String(text||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(part=>{const m=part.match(/^(\d+)\s*-\s*(\d+)$/);if(m){let a=+m[1],b=+m[2];if(a>b)[a,b]=[b,a];for(let i=a;i<=b;i++)if(i>=1&&i<=max)set.add(i)}else{const n=+part;if(n>=1&&n<=max)set.add(n)}});return[...set].sort((a,b)=>a-b)}
  async function renderSplitPages(){ui.content.innerHTML='<div class="pdf-pages pdf-select-pages" data-split-grid></div>';const grid=$('[data-split-grid]',ui.content);for(let i=0;i<state.pdfPageCount;i++){const card=document.createElement('button');card.type='button';card.className=`pdf-select-card${state.splitSelected.has(i)?' is-selected':''}`;card.innerHTML=`<div class="pdf-page-preview"><canvas></canvas><span class="pdf-check-mark">✓</span><span class="pdf-select-number">${i+1}</span></div><strong>Page ${i+1}</strong>`;card.addEventListener('click',()=>{state.splitSelected.has(i)?state.splitSelected.delete(i):state.splitSelected.add(i);renderSplitPages()});grid.appendChild(card);await renderThumb(state.pdfjsDoc,i+1,$('canvas',card),{maxW:190,maxH:235});if(i%5===4)await tick()}}
  async function makePdfFromIndices(indices){const src=await PDFDocument.load(await state.files[0].arrayBuffer()),out=await PDFDocument.create(),copies=await out.copyPages(src,indices);copies.forEach(p=>out.addPage(p));return out.save({useObjectStreams:true})}
  async function extractPages(){const indices=[...state.splitSelected].sort((a,b)=>a-b);if(!indices.length){showMessage('Sélectionne au moins une page.','error');return}setBusy(true);progress('Extraction…',10);try{downloadBytes(await makePdfFromIndices(indices),`${baseName(state.files[0].name)}-selection.pdf`);showMessage(`${indices.length} page${indices.length>1?'s':''} exportée${indices.length>1?'s':''}.`)}finally{hideProgress();setBusy(false)}}
  async function exportEachSelectedPage(){const indices=[...state.splitSelected].sort((a,b)=>a-b);if(!indices.length){showMessage('Sélectionne au moins une page.','error');return}setBusy(true);progress('Pages séparées…',4);try{const zip=new JSZip();for(let i=0;i<indices.length;i++){zip.file(`page-${String(indices[i]+1).padStart(3,'0')}.pdf`,await makePdfFromIndices([indices[i]]));progress(`Page ${i+1}/${indices.length}`,5+75*(i+1)/indices.length)}const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'},m=>progress('Création du ZIP…',80+m.percent*.19));downloadBytes(blob,`${baseName(state.files[0].name)}-pages.zip`,'application/zip');showMessage('Pages sélectionnées exportées séparément.')}finally{hideProgress();setBusy(false)}}
  async function splitIntoChunks(){const size=Math.max(1,Math.round(Number($('[data-chunk-size]',ui.controls)?.value)||5)),indices=[...state.splitSelected].sort((a,b)=>a-b);if(!indices.length){showMessage('Sélectionne au moins une page.','error');return}setBusy(true);progress('Découpage…',5);try{const zip=new JSZip();for(let i=0;i<indices.length;i+=size){const chunk=indices.slice(i,i+size);zip.file(`lot-${String(i/size+1).padStart(2,'0')}.pdf`,await makePdfFromIndices(chunk));progress('Découpage…',10+70*Math.min(1,(i+size)/indices.length))}const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'},m=>progress('Création du ZIP…',82+m.percent*.17));downloadBytes(blob,`${baseName(state.files[0].name)}-lots.zip`,'application/zip');showMessage('Lots créés à partir de la sélection.')}finally{hideProgress();setBusy(false)}}

