      for(let i=1;i<=Math.min(info.pages,4);i++){const f=document.createElement('figure');f.innerHTML='<div><canvas></canvas></div><figcaption></figcaption>';$('figcaption',f).textContent=`Page ${i}`;box.appendChild(f);await renderThumb(pdfjs,i,$('canvas',f),{maxW:140,maxH:180})}
