  /* Outils complémentaires, entièrement locaux. */
  function strictPageRange(value,count){
    if(!String(value).trim())return Array.from({length:count},(_,i)=>i+1);
    const parts=String(value).split(',').map(v=>v.trim());
    if(parts.some(p=>!/^\d+(?:\s*-\s*\d+)?$/.test(p)))throw new Error('Indiquez des pages comme 1-3, 5, 8.');
    for(const p of parts){const ns=p.split('-').map(Number);if(ns.some(n=>!Number.isInteger(n)||n<1||n>count))throw new Error(`Les pages doivent être comprises entre 1 et ${count}.`);}
    return parseRanges(value,count);
  }
