  document.addEventListener('change',e=>{const t=e.target;if(!t.matches('[data-ann-prop]'))return;const a=state.editorAnnotations.find(a=>a.id===state.editorSelected);if(!a)return;const k=t.dataset.annProp;if(k==='text'||k==='color')a[k]=t.value;else if(k==='fontSize')a[k]=clamp(t.value,6,96);else if(k==='opacity')a[k]=clamp(t.value,5,100)/100;else if(k==='x'||k==='y')a[k]=clamp(Number(t.value)/100,0,1-a[k==='x'?'w':'h']);else a[k]=clamp(Number(t.value)/100,.02,1-a[k==='w'?'x':'y']);renderEditorLayer();pushEditorHistory();});
  document.addEventListener('keydown',e=>{if(state.tool!=='edit'||state.busy||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();restoreEditorHistory(e.shiftKey?1:-1);}if(e.key.toLowerCase()==='y'){e.preventDefault();restoreEditorHistory(1);}if(e.key.toLowerCase()==='d'){e.preventDefault();$('[data-editor-duplicate]')?.click();}}});

  document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const modal=ui.library&&!ui.library.hidden?ui.library:ui.finalPreview&&!ui.finalPreview.hidden?ui.finalPreview:null;if(!modal)return;const panel=modal.querySelector('[role="dialog"]'),items=[...panel.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||!panel.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!panel.contains(document.activeElement))){e.preventDefault();first.focus();}});
